// The room is warm iff the dial never goes above 1 and is not at its lowest point.
function visible(actions) {
  let dial = 0;
  let min = 0;
  let tooHigh = false;

  for (const action of actions) {
    if (action === "turn up") dial += 1;
    else if (action === "turn down") dial -= 1;
    // "wait" leaves the dial unchanged

    if (dial > 1) tooHigh = true;
    if (dial < min) min = dial;
  }

  return { room: (!tooHigh && dial !== min) ? "warm" : "cold" };
}

