  // Dial positions -1,0,1,2 start at 0; room starts warm. Up from -1 to 0 warms; up to 2 or down to -1 cools; otherwise temperature unchanged.
  let dial = 0;
  let room = "warm";
  for (const action of actions) {
    if (action === "turn up") {
      if (dial < 2) dial++;
      if (dial === 0) room = "warm";
      else if (dial === 2) room = "cold";
    } else if (action === "turn down") {
      if (dial > -1) dial--;
      if (dial === -1) room = "cold";
    }
  }
  return { room };
}

