  const s = actions.filter(a => a !== "wait").map(a => a === "turn up" ? "U" : "D").join("");
  if (s.length === 0) return { room: "cold" };
  if (s[0] === "U") {
    if (s.length >= 2 && s[1] === "U") return { room: "cold" };
    return { room: "warm" };
